pub(crate) fn init(config: &Config) -> Result<Value, String> {
    if config.db.exists() {
        return Err("IdentityConflict：init拒绝覆盖已有库".into());
    }
    let revision = config.revision()?;
    let (mut c, runtime) = open(&config.db, false)?;
    let tx = c.transaction().map_err(err)?;
